/// V3 — every field at the extreme of its Soroban type (encoding only; the contract would
/// reject it). Pins the word encoding of each integer width.
fn v3(env: &Env) -> DroughtDetermination {
    DroughtDetermination {
        on_chain_policy_id: u64::MAX,
        damage_percent_bp: u32::MAX,
        drought_damage: u32::MAX,
        payout_amount: i128::MIN,
        assessed_at: u64::MAX,
        latitude_e6: i128::MIN,
        longitude_e6: i128::MAX,
        sum_insured: i128::MAX,
        season_start_epoch: u64::MAX,
        lgp_days: u32::MAX,
        rain_w1_e2: u128::MAX,
        rain_ref_w1_e2: u128::MAX,
        rain_w2_e2: u128::MAX,
        rain_ref_w2_e2: u128::MAX,
        cdd_w2_days: u32::MAX,
        source_hash: BytesN::from_array(env, &[0xff; 32]),
        methodology_params_hash: BytesN::from_array(env, &[0xff; 32]),
    }
}

struct Vectors {
    inputs: String,
    inputs_hash: String,
    preimage: String,
    digest: String,
}

fn vectors(env: &Env, d: &DroughtDetermination, contract: &str, domain: [u8; 32]) -> Vectors {
    let contract = Address::from_str(env, contract);
    let domain = BytesN::from_array(env, &domain);
    let inputs = encode_drought_inputs(env, d);
    let inputs_hash = env.crypto().keccak256(&inputs).to_bytes();
    let preimage = encode_drought_preimage(env, &inputs_hash, d, &contract, &domain);
    let digest = drought_determination_digest(env, d, &contract, &domain);
    assert_eq!(inputs.len(), DROUGHT_INPUTS_LEN);
    assert_eq!(preimage.len(), DROUGHT_PREIMAGE_LEN);
    assert_eq!(digest.to_array(), env.crypto().keccak256(&preimage).to_array());
    Vectors {
        inputs: bytes_hex(&inputs),
        inputs_hash: hex(&inputs_hash.to_array()),
        preimage: bytes_hex(&preimage),
        digest: hex(&digest.to_array()),
    }
}

/// Pinned drought vectors. Run with `--nocapture` to print them for the oracle test. All three
/// were also rebuilt, byte for byte, from the oracle's existing `stellar.shared.js` helpers
/// (`stellarWord`, `stellarContractAddressXdr`) and ethers v6 keccak256 in a throwaway copy.
#[test]
fn drought_golden_vectors() {
    let env = Env::default();
    let cases = [
        ("V1", v1(&env), TESTNET_PR, TESTNET_DOMAIN),
        ("V2", v2(&env), TESTNET_PR, MAINNET_DOMAIN),
        ("V3", v3(&env), TESTNET_PR, TESTNET_DOMAIN),
    ];
    let mut got = std::vec::Vec::new();
    for (name, d, c, dom) in cases.iter() {
        let v = vectors(&env, d, c, *dom);
        std::println!("{} contract    {}", name, c);
        std::println!("{} domain      {}", name, hex(dom));
        std::println!("{} inputs      {}", name, v.inputs);
        std::println!("{} inputsHash  {}", name, v.inputs_hash);
        std::println!("{} preimage    {}", name, v.preimage);
        std::println!("{} digest      {}", name, v.digest);
        got.push((v.inputs_hash, v.digest));
    }
    let pinned = [
        (PIN_V1_INPUTS_HASH, PIN_V1_DIGEST),
        (PIN_V2_INPUTS_HASH, PIN_V2_DIGEST),
        (PIN_V3_INPUTS_HASH, PIN_V3_DIGEST),
    ];
    for (i, (ih, dg)) in pinned.iter().enumerate() {
        assert_eq!(got[i].0, *ih, "V{} inputsHash drifted", i + 1);
        assert_eq!(got[i].1, *dg, "V{} digest drifted", i + 1);
    }
}

const PIN_V1_INPUTS_HASH: &str =
    "0x5dddcbb1cff2a508d0aae6eaf1426365e5eeebea7150c1b528db0b4fa77ac235";
const PIN_V1_DIGEST: &str = "0x1c6d4c5891f94f1f91d9215a2cb40bb11150abbbd609bda8101025af6f45409a";
const PIN_V2_INPUTS_HASH: &str =
    "0xf17005d1f41e64360433b148912a9af83ee779c2273fcb3ab91ba545e2331501";
const PIN_V2_DIGEST: &str = "0x608524c93198e2c17650cfb9a4f6a92477885e9ed22afdce5863deec55da9890";
const PIN_V3_INPUTS_HASH: &str =
    "0x01a3ebb1d1a1a8a604eb0e3bb13227673dfc15d43610166d60d3dc892f9e5157";
const PIN_V3_DIGEST: &str = "0xde0104e3c3957dc0e6440ea10af139cabf1722be2caa304c77224da43d11da92";

#[test]
fn drought_preimage_layout_and_offsets() {
    let env = Env::default();
    let d = v1(&env);
    let contract = Address::from_str(&env, TESTNET_PR);
    let domain = BytesN::from_array(&env, &TESTNET_DOMAIN);
    let inputs = encode_drought_inputs(&env, &d);
    let ih = env.crypto().keccak256(&inputs).to_bytes();
    let p = encode_drought_preimage(&env, &ih, &d, &contract, &domain);
    assert_eq!(p.len(), 360);
    let at = |from: u32, to: u32| -> std::vec::Vec<u8> { p.slice(from..to).iter().collect() };
    assert_eq!(
        hex(&at(0, 32)),
        hex(&keccak_of(&env, b"1.0")),
        "schema word"
    );
    assert_eq!(
        hex(&at(32, 64)),
        "0xf2b99be7d15886c701cace71237751b285d7a5efd670dd4827b70222b4f2b6fe"
    );
    assert_eq!(
        hex(&at(64, 96)),
        "0x25e8b6bc86f982a1af7056c2ef67b624936c3ca109202f7ff94c543635fa6891"
    );
    assert_eq!(at(96, 128), TESTNET_DOMAIN.to_vec());
    assert_eq!(hex(&at(128, 136)), "0x0000001200000001");
    assert_eq!(at(168, 200), ih.to_array().to_vec());
    // Result words: policy id, bp, drought damage, payout, assessed_at.
    let word = |i: u32| at(200 + 32 * i, 232 + 32 * i);
    assert_eq!(word(0)[31], 1);
    assert_eq!(&word(1)[30..], &[0x11, 0x94]); // 4500
    assert_eq!(word(2)[31], 45);
    assert_eq!(&word(3)[24..], &4_500_000_000u64.to_be_bytes());
    assert_eq!(&word(4)[24..], &(1_743_465_600u64 + 117 * 86_400).to_be_bytes());
    // Inputs: 13 words; the two hashes are copied raw at the end.
    assert_eq!(inputs.len(), 416);
    let iw: std::vec::Vec<u8> = inputs.slice(352..384).iter().collect();
    assert_eq!(iw, SOURCE_HASH.to_vec());
    let iw: std::vec::Vec<u8> = inputs.slice(384..416).iter().collect();
    assert_eq!(iw, DROUGHT_PARAMS_HASH_RDI_1_0.to_vec());
    // Negative latitude sign-extends through the high 16 bytes.
    let lat: std::vec::Vec<u8> = inputs.slice(32..64).iter().collect();
    assert!(lat[..16].iter().all(|b| *b == 0xff));
}

/// The 13-word inputs layout is byte-identical to the EVM `abi.encode`: with the EVM
/// conformance fixture's values (6dp sum insured, its arbitrary params hash) the Soroban
/// encoder reproduces the inputs hash that Solidity, the oracle and the backend all pin
/// (`DroughtConformance.t.sol` `FIXTURE_INPUTS_HASH`, microcrop-contracts@ae163d1).
#[test]
fn drought_inputs_match_the_evm_conformance_fixture() {
    let env = Env::default();
    let d = DroughtDetermination {
        on_chain_policy_id: 12_345,
        damage_percent_bp: 4_500,
        drought_damage: 45,
        payout_amount: 450_000_000,
        assessed_at: 1_717_200_000,
        latitude_e6: -1_286_389,
        longitude_e6: 36_817_223,
        sum_insured: 1_000_000_000,
        season_start_epoch: 1_710_460_800,
        lgp_days: 180,
        rain_w1_e2: 12_500,
        rain_ref_w1_e2: 20_000,
        rain_w2_e2: 3_000,
        rain_ref_w2_e2: 18_000,
        cdd_w2_days: 21,
        source_hash: BytesN::from_array(&env, &SOURCE_HASH),
        methodology_params_hash: BytesN::from_array(
            &env,
            &hex32("22ff3772b000bcf21ae06e8321f6e9eadb2d1ec524fea06f65d60f4b39940ffb"),
        ),
    };
    let ih = env.crypto().keccak256(&encode_drought_inputs(&env, &d));
    assert_eq!(
        hex(&ih.to_array()),
        "0xe6e25b7654138fdface20c80b1b4c20cbc63d95d198d93331c4dc24cb9022976"
    );
}

#[test]
fn params_hash_is_keccak_of_the_params_json() {
    let env = Env::default();
    let h = env
        .crypto()
        .keccak256(&Bytes::from_slice(&env, DROUGHT_PARAMS_JSON.as_bytes()));
    assert_eq!(h.to_array(), DROUGHT_PARAMS_HASH_RDI_1_0);
    assert_eq!(
        hex(&DROUGHT_PARAMS_HASH_RDI_1_0),
        "0x2580afa0002f8ae349ad078ffea429049ab1c1146be2c56b82f3e45a7cc447cf"
    );
}

/// A crop determination and a drought determination never share a digest: the kind word,
/// the methodology word and the preimage length all differ.
#[test]
fn crop_and_drought_digests_are_domain_separated() {
    let env = Env::default();
    let contract = Address::from_str(&env, TESTNET_PR);
    let domain = BytesN::from_array(&env, &TESTNET_DOMAIN);
    let crop = CropDetermination {
        on_chain_policy_id: 1,
        damage_percent_bp: 4_500,
        weather_damage: 45,
        satellite_damage: 45,
        payout_amount: 4_500_000_000,
        assessed_at: 1_743_465_600 + 117 * 86_400,
        latitude_e6: -1_286_389,
        longitude_e6: 36_817_223,
        sum_insured: 10_000_000_000,
        ndvi_scaled: 0,
        weather_present: 1,
        weather_temp_c_e2: 0,
        weather_precip_e2: 0,
        weather_humidity: 0,
        weather_wind_e2: 0,
    };
    let ci = env.crypto().keccak256(&encode_inputs(&env, &crop)).to_bytes();
    let cp = encode_preimage(&env, &ci, &crop, &contract, &domain);
    let d = v1(&env);
    let di = env
        .crypto()
        .keccak256(&encode_drought_inputs(&env, &d))
        .to_bytes();
    let dp = encode_drought_preimage(&env, &di, &d, &contract, &domain);
    assert_eq!(cp.len(), 392);
    assert_eq!(dp.len(), 360);
    assert_ne!(cp.slice(32..64), dp.slice(32..64), "kind words must differ");
    assert_ne!(cp.slice(64..96), dp.slice(64..96), "methodology words must differ");
    // keccak256("CROP_DAMAGE") = 0x5f9a…
    assert!(hex(&cp.slice(32..64).iter().collect::<std::vec::Vec<u8>>()).starts_with("0x5f9a"));
    assert_ne!(
        determination_digest(&env, &crop, &contract, &domain).to_array(),
        drought_determination_digest(&env, &d, &contract, &domain).to_array()
    );
}

/// Signature conformance, JS -> Rust: V1's digest signed by ethers v6
/// `new SigningKey(TEST_PRIVATE_KEY).sign(digest)` (the oracle's test key,
/// `src/chain/crop-action.test.ts`) recovers, through the host's `secp256k1_recover`, to that
/// key's uncompressed public key.
#[test]
fn js_signature_over_v1_recovers_to_the_test_key() {
    let env = Env::default();
    let d = v1(&env);
    let contract = Address::from_str(&env, TESTNET_PR);
    let domain = BytesN::from_array(&env, &TESTNET_DOMAIN);
    let digest = drought_determination_digest(&env, &d, &contract, &domain);
    assert_eq!(hex(&digest.to_array()), PIN_V1_DIGEST);
    let mut sig = [0u8; 64];
    sig[..32].copy_from_slice(&hex32(JS_V1_SIG_R));
    sig[32..].copy_from_slice(&hex32(JS_V1_SIG_S));
    let recovered = env.crypto().secp256k1_recover(
        &digest,
        &BytesN::from_array(&env, &sig),
        JS_V1_RECOVERY_ID,
    );
    let pk = recovered.to_array();
    assert_eq!(pk[0], 0x04);
    assert_eq!(hex(&pk[1..33]), JS_TEST_PUBKEY_X);
    assert_eq!(hex(&pk[33..]), JS_TEST_PUBKEY_Y);
}

const JS_V1_SIG_R: &str = "b0f24d171bf0483e00415c260c74b5a4d2114b1e5d40c6fdfe77a9ba205717c6";
const JS_V1_SIG_S: &str = "1ccd2fbe2f33550348c9e982083ccf627ccf0d374d06ee9434da52ff06976cc4";
/// ethers `v = 28` -> recovery id 1.
const JS_V1_RECOVERY_ID: u32 = 1;
/// `new SigningKey(TEST_PRIVATE_KEY).publicKey` = `0x04 ‖ X ‖ Y`.
const JS_TEST_PUBKEY_X: &str =
    "0xba5734d8f7091719471e7f7ed6b9df170dc70cc661ca05e688601ad984f068b0";
const JS_TEST_PUBKEY_Y: &str =
    "0xd67351e5f06073092499336ab0839ef8a521afd334e53807205fa2f08eec74f4";
